// A small controlled experiment: plaintext bigrams -> q4 for K1, K2 disclosed.
// Equal annealing proposal budget to the previous oracle, NOT the complete
// adjacency/alignment algorithm from Lasry's thesis and NOT a BLUME attack.
#define main baseline_cli_main
#include "../crypto/double_search.cpp"
#undef main
double bigscore(const Ms&ct,const V&k,const V&knownk2,const Model&m){double s=0;int n=0;for(auto&a:ct){V p=crypt(a,k,knownk2,0,false);for(size_t i=1;i<p.size();i++){s+=m.b[p[i-1]*26+p[i]];n++;}}return s/n;}
int main(int argc,char**argv){if(argc!=7)return 2;Model m(argv[1]);V body=read(argv[2]);int w1=std::stoi(argv[3]),w2=std::stoi(argv[4]),seed=std::stoi(argv[5]),steps=std::stoi(argv[6]);RNG plant_rng(seed);int pos=plant_rng()%(body.size()-774);Ms pt={V(body.begin()+pos,body.begin()+pos+615),V(body.begin()+pos+615,body.begin()+pos+775)};V tk1=perm(w1,plant_rng),tk2=perm(w2,plant_rng);Ms ct;for(auto&a:pt)ct.push_back(crypt(a,tk1,tk2,0,true));uint64_t ss=uint64_t(seed)^0x9e3779b97f4a7c15ULL;auto start=std::chrono::steady_clock::now();for(int msgs:{1,2}){Ms used(ct.begin(),ct.begin()+msgs);RNG rng(ss^0xaaaaaaaaaaaaaaaaULL);auto fb=[&](const V&k){return bigscore(used,k,tk2,m);};auto fq=[&](const V&k){return fullscore(used,k,tk2,0,m,4);};std::pair<double,V>best={-1e100,{}};for(int rr=0;rr<3;rr++){auto first=anneal(perm(w1,rng),steps*2,rng,fb,.02,.0002);auto second=anneal(first.second,steps*2,rng,fq,.03,.0005);if(second.first>best.first)best=second;}best=slides(best.second,steps,fq);V counts;for(int i=0;i<2;i++)counts.push_back(correct(crypt(ct[i],best.second,tk2,0,false),pt[i]));std::cout<<std::setprecision(10)<<"{\"diagnostic\":\"oracle_bigram_then_q4\",\"w1\":"<<w1<<",\"w2\":"<<w2<<",\"plant_seed\":"<<seed<<",\"messages_scored\":"<<msgs<<",\"k2_revealed\":true,\"k1_exact\":"<<(best.second==tk1?"true":"false")<<",\"correct_letters\":"<<keyjson(counts)<<",\"q4\":"<<best.first<<",\"q4_truth\":"<<fq(tk1)<<",\"annealing_proposals\":"<<steps*12<<",\"elapsed_cumulative_seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"}\n"<<std::flush;}return 0;}
